CREATE TABLE "localidad" (
  "id_localidad" smallint PRIMARY KEY,
  "nombre_localidad" varchar(80) UNIQUE NOT NULL
);

CREATE TABLE "sector" (
  "id_sector" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre_sector" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "objetivo_estrategico" (
  "id_objetivo" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo_objetivo" smallint UNIQUE,
  "nombre_objetivo" varchar(150) NOT NULL
);

CREATE TABLE "programa" (
  "id_programa" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_objetivo" smallint NOT NULL,
  "codigo_programa" smallint,
  "nombre_programa" varchar(200) NOT NULL
);

CREATE TABLE "proyecto" (
  "id_proyecto" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo_proyecto" varchar(10) NOT NULL,
  "id_localidad" smallint NOT NULL,
  "id_programa" smallint,
  "nombre_proyecto" varchar(200) NOT NULL
);

CREATE TABLE "meta_proyecto" (
  "id_meta" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo_meta_extendida" varchar(10) UNIQUE NOT NULL,
  "id_proyecto" int NOT NULL,
  "id_sector" smallint NOT NULL,
  "codigo_indicador" varchar(10) UNIQUE,
  "indicador_producto" text,
  "descripcion_meta" text NOT NULL,
  "componente_proyecto" varchar(100),
  "linea_inversion" varchar(150),
  "concepto_gasto" varchar(200),
  "componente_presupuestal" varchar(80),
  "meta_total_2025_2028" decimal(18,2),
  "tipo_anualizacion" varchar(30)
);

CREATE TABLE "poai" (
  "id_poai" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_meta" int NOT NULL,
  "vigencia" smallint NOT NULL,
  "recurso_indicativo" decimal(18,2),
  "porcentaje_plan_plurianual" decimal(9,6),
  "magnitud_programada" decimal(18,4),
  "valor_poai" decimal(18,2),
  "porcentaje_recursos_poai" decimal(9,6),
  "tiene_propuesta_pp" boolean,
  "fecha_corte" date
);

CREATE TABLE "propuesta_ciudadana" (
  "id_propuesta" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo_propuesta" varchar(20) UNIQUE NOT NULL,
  "id_meta" int NOT NULL,
  "nombre_propuesta" varchar(300) NOT NULL,
  "metodologia" varchar(80),
  "tipo_acuerdo" text
);

CREATE TABLE "seguimiento_propuesta" (
  "id_seguimiento" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_propuesta" bigint NOT NULL,
  "vigencia_ejecucion" smallint,
  "fecha_corte" date NOT NULL,
  "se_ejecuta_con_recursos" boolean,
  "estado_propuesta" varchar(50),
  "poblacion_beneficiada" int,
  "clasificacion_poblacional" varchar(150),
  "avance_gestion" text,
  "dificultades" text
);

CREATE TABLE "crp" (
  "id_crp" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "numero_crp" varchar(20) NOT NULL,
  "vigencia" smallint NOT NULL,
  "fecha_registro" date,
  "numero_compromiso" varchar(30),
  "tipo_compromiso" varchar(100),
  "plazo" int,
  "objeto" text,
  "codigo_modalidad" varchar(10),
  "modalidad_seleccion" varchar(100),
  "tipo_documento_beneficiario" varchar(20)
);

CREATE TABLE "crp_meta" (
  "id_crp_meta" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_crp" bigint NOT NULL,
  "id_meta" int NOT NULL,
  "valor_asignado_pp" decimal(18,2)
);

CREATE TABLE "crp_propuesta" (
  "id_crp" bigint NOT NULL,
  "id_propuesta" bigint NOT NULL,
  PRIMARY KEY ("id_crp", "id_propuesta")
);

CREATE TABLE "seguimiento_meta" (
  "id_seguimiento_meta" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_meta" int NOT NULL,
  "vigencia" smallint NOT NULL,
  "fecha_corte" date NOT NULL,
  "magnitud_programada" decimal(18,4),
  "magnitud_contratada" decimal(18,4),
  "magnitud_entregada" decimal(18,4),
  "presupuesto_programado" decimal(18,2),
  "compromisos" decimal(18,2),
  "giros" decimal(18,2)
);

CREATE TABLE "ods" (
  "id_ods" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "codigo_ods" varchar(10) UNIQUE NOT NULL,
  "nombre_ods" varchar(150),
  "esfera_ods" varchar(50)
);

CREATE TABLE "meta_ods" (
  "id_meta_ods" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_ods" smallint NOT NULL,
  "codigo_meta_ods" varchar(20) UNIQUE NOT NULL,
  "descripcion_meta_ods" text
);

CREATE TABLE "meta_ods_relacion" (
  "id_meta" int NOT NULL,
  "id_meta_ods" int NOT NULL,
  PRIMARY KEY ("id_meta", "id_meta_ods")
);

CREATE TABLE "tipo_peticion" (
  "id_tipo_peticion" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre_tipo_peticion" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "medio_recepcion" (
  "id_medio_recepcion" SMALLINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre_medio" varchar(80) UNIQUE NOT NULL
);

CREATE TABLE "subtema_pqrs" (
  "id_subtema" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre_subtema" varchar(300) UNIQUE NOT NULL
);

CREATE TABLE "pqrs" (
  "id_pqrs" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "radicado" varchar(30) UNIQUE NOT NULL,
  "numero_sdqs" varchar(30),
  "id_localidad" smallint NOT NULL,
  "id_tipo_peticion" smallint,
  "id_medio_recepcion" smallint,
  "id_subtema" int,
  "fecha_registro" timestamp,
  "fecha_radicacion" timestamp,
  "fecha_asignacion" timestamp,
  "vigencia" smallint,
  "tiempo_tramite" decimal(10,2),
  "estado_orfeo" varchar(50),
  "observacion_general" text,
  "observacion_sac" text,
  "usuario_actual" varchar(100),
  "dependencia_actual" varchar(150),
  "ultima_dependencia" varchar(150),
  "radicado_respuesta" varchar(30),
  "fecha_respuesta" timestamp,
  "fecha_seguimiento" timestamp,
  "codigo_localidad_fuente" varchar(20)
);

CREATE UNIQUE INDEX ON "programa" ("id_objetivo", "codigo_programa");

CREATE UNIQUE INDEX ON "proyecto" ("id_localidad", "codigo_proyecto");

CREATE UNIQUE INDEX ON "poai" ("id_meta", "vigencia");

CREATE UNIQUE INDEX ON "seguimiento_propuesta" ("id_propuesta", "fecha_corte");

CREATE UNIQUE INDEX ON "crp" ("numero_crp", "vigencia");

CREATE UNIQUE INDEX ON "seguimiento_meta" ("id_meta", "vigencia", "fecha_corte");

ALTER TABLE "programa" ADD FOREIGN KEY ("id_objetivo") REFERENCES "objetivo_estrategico" ("id_objetivo") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "proyecto" ADD FOREIGN KEY ("id_localidad") REFERENCES "localidad" ("id_localidad") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "proyecto" ADD FOREIGN KEY ("id_programa") REFERENCES "programa" ("id_programa") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "meta_proyecto" ADD FOREIGN KEY ("id_proyecto") REFERENCES "proyecto" ("id_proyecto") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "meta_proyecto" ADD FOREIGN KEY ("id_sector") REFERENCES "sector" ("id_sector") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "poai" ADD FOREIGN KEY ("id_meta") REFERENCES "meta_proyecto" ("id_meta") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "propuesta_ciudadana" ADD FOREIGN KEY ("id_meta") REFERENCES "meta_proyecto" ("id_meta") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "seguimiento_propuesta" ADD FOREIGN KEY ("id_propuesta") REFERENCES "propuesta_ciudadana" ("id_propuesta") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "crp_meta" ADD FOREIGN KEY ("id_crp") REFERENCES "crp" ("id_crp") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "crp_meta" ADD FOREIGN KEY ("id_meta") REFERENCES "meta_proyecto" ("id_meta") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "crp_propuesta" ADD FOREIGN KEY ("id_crp") REFERENCES "crp" ("id_crp") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "crp_propuesta" ADD FOREIGN KEY ("id_propuesta") REFERENCES "propuesta_ciudadana" ("id_propuesta") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "seguimiento_meta" ADD FOREIGN KEY ("id_meta") REFERENCES "meta_proyecto" ("id_meta") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "meta_ods" ADD FOREIGN KEY ("id_ods") REFERENCES "ods" ("id_ods") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "meta_ods_relacion" ADD FOREIGN KEY ("id_meta") REFERENCES "meta_proyecto" ("id_meta") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "meta_ods_relacion" ADD FOREIGN KEY ("id_meta_ods") REFERENCES "meta_ods" ("id_meta_ods") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pqrs" ADD FOREIGN KEY ("id_localidad") REFERENCES "localidad" ("id_localidad") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pqrs" ADD FOREIGN KEY ("id_tipo_peticion") REFERENCES "tipo_peticion" ("id_tipo_peticion") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pqrs" ADD FOREIGN KEY ("id_medio_recepcion") REFERENCES "medio_recepcion" ("id_medio_recepcion") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pqrs" ADD FOREIGN KEY ("id_subtema") REFERENCES "subtema_pqrs" ("id_subtema") DEFERRABLE INITIALLY IMMEDIATE;
